    const d = new Date(Number(v));
    return (d.getUTCHours() === 0 ? d : new Date(d.getTime() + OFFSET * 3600e3)).toISOString().slice(0, 10);
  }
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
